                  Version {state.liveVersion} is live
                </h2>
                <p className='text-muted-foreground text-[13px]'>
                  Every new conversation uses it. The version before it is kept
                  for a rollback.
                </p>
              </div>
              <Button
                type='button'
                data-review-first
                onClick={onClose}
                className='self-end'
